%[text] ## Load, clean, and build SARIMA + Fourier Regressors model
%[text] This script explores the electricity usage dataset for a single client. The main idea is to use a fourier regression (using sine and cosine) to capture the yearly trend, then using a SARIMA model to capture the weekly trend. First the fourier model is fit - this is used to capture the residual values, which are then used to determine the parameters for SARIMA through ACF and PACF. Then, the model is fit - we refit the fourier regression in tandem with the SARIMA model, rather than using the original fit (through regARIMA).
%[text] 
%[text] TODO 
%[text] - Add in holiday indicator? As is, the model can't capture the spike during the holidays (late dec, early jan)
%[text] - Add in a day of week dummy variable
%[text] - implement rolling forecast \
clear; clc; close all
%%
%[text] Load dataset
opts = detectImportOptions('LD2011_2014.txt', ...
    'Delimiter', ';', 'DecimalSeparator', ',');

opts = setvartype(opts, 1, 'datetime');
opts = setvaropts(opts, 1, 'InputFormat', 'yyyy-MM-dd HH:mm:ss');
T = readtable('LD2011_2014.txt', opts);
T.Properties.VariableNames{1} = 'Time';
TT = table2timetable(T, 'RowTimes', 'Time');
%%
%[text] Choose client, combine into weekly avg
client = 'MT_103';
x = TT(:, client);

% Trim leading zeros (before client connected)
first = find(x.(client) > 0, 1);
x = x(first:end, :);

% Combine into daily readings
xw = retime(x, 'daily', 'mean');
%%
%[text] Plot
plot(xw.Time, xw.(client)); title('Raw Data') %[output:880497d9]
%%
%[text] Train-Test split
trainRange = xw.Time(1):days(1):xw.Time(1)+years(3);
testRange = xw.Time(1)+years(2)+days(1):days(1):xw.Time(end);

yTrain = xw.(client)(trainRange);
timeTrain = xw.Time(trainRange);
%%
%[text] Normalize - From ADF test for stationarity, h = 1 =\> no need to difference
yMean = mean(yTrain);
yStd = std(yTrain);

yNorm = (yTrain - yMean) / yStd;
plot(timeTrain, yNorm); title('Normalized Training Data') %[output:3bad63b5]
adftest(yNorm) %[output:79036eb9]
%%
%[text] Yearly Fourier terms - captures yearly trend, while SARIMA will capture weekly seasonality
t = days(timeTrain - timeTrain(1));
m = 365.25; % yearly cycle
n = numel(t);

% Choosing K - elbow at 2
Kmax = 8;
aicK = zeros(Kmax,1);
for K = 1:Kmax
    Xk = zeros(n, 2*K);
    for k = 1:K
        Xk(:,2*k-1) = sin(2*pi*k*t/m);
        Xk(:,2*k)   = cos(2*pi*k*t/m);
    end
    aicK(K) = fitlm(Xk, yNorm(:)).ModelCriterion.AIC;
end
figure; plot(1:Kmax, aicK, '-o'); xlabel('K'); ylabel('AIC') %[output:2cdf35fc]

% Compute w/ chosen K value
K = 2;
X = zeros(n, 2*K); % Two cols per harmonic
for k = 1:K
    X(:, 2*k-1) = sin(2*pi*k*t/m);
    X(:, 2*k) = cos(2*pi*k*t/m);
end

Xext = [ones(n, 1) X]; % adds intercept col
beta = Xext \ yNorm(:); % least-squares coeff
yFourier = Xext * beta; % Fit curve

figure %[output:61149cfb]
plot(timeTrain, yNorm, 'Color', [0.7 0.7 0.7]); hold on %[output:61149cfb]
plot(timeTrain, yFourier, 'r', 'LineWidth', 2); hold off %[output:61149cfb]
legend('yNorm', 'Fourier fit'); title(sprintf('Yearly Fourier fit, K = %d', K)) %[output:61149cfb]
%%
%[text] Get residuals between yearly fourier and yNorm - this is what we will use SARIMA on. h = 1 -\> stationary
yRes = yNorm - yFourier;
figure; plot(timeTrain, yRes); title('Residuals after yearly Fourier fit') %[output:0ec648f1]
h = adftest(yRes) %[output:92456b91]

figure; autocorr(yRes, NumLags=40); title('ACF of residuals') %[output:4c1fa002]
figure; parcorr(yRes, NumLags=40); title('PACF of residuals') %[output:40fbfa14]
%[text] p = 1, q = 0
%[text] P = 1, Q = 0 or P = 0, Q = 1 (try both options)
%[text] also try P = Q  = 1
%[text] s = 7
%%
%[text] Fit joint model — Fourier and SARIMA
%[text] Parameters
%[text] (1, 0, 0) - baseline AR(1) model
%[text] (1, 0, 0) x (1, 0, 0)\_7 - seasonal AR
%[text] (1, 0, 0) x (0, 0, 1)\_7 - seasonal MA
%[text] (1, 0, 0) x (1, 0, 1)\_7 - seasonal ARMA
%[text] 
y = yNorm(:);
n = numel(y);

% Fourier
K = 2; m = 365.25;
tTrain = days(timeTrain - timeTrain(1));

X = zeros(n, 2*K); % Two cols per harmonic
for k = 1:K
    X(:, 2*k-1) = sin(2*pi*k*tTrain/m);
    X(:, 2*k) = cos(2*pi*k*tTrain/m);
end

% [p q P Q]
candidates = [ 1 0 0 0;    % #1 AR(1) baseline %[output:group:159ec624] %[output:7cdfae83]
    1 0 1 0;    % #2 + seasonal AR(7) %[output:7cdfae83]
    1 0 0 1;    % #3 + seasonal MA(7) %[output:7cdfae83]
    1 0 1 1;]    % #4 + ARMA %[output:group:159ec624] %[output:7cdfae83]

nC = size(candidates,1);
AIC = zeros(nC,1); BIC = zeros(nC,1); LogL = zeros(nC,1);
models = cell(nC,1);

for i = 1:nC
    c = num2cell(candidates(i,:));
    [p,q,P,Q] = c{:};

    [models{i}, LogL(i), k] = fitRegSARIMA(y, X, p, q, P, Q);
    [AIC(i), BIC(i)] = aicbic(LogL(i), k, n);
end

results = table((1:nC)', candidates(:,1), candidates(:,2), candidates(:,3), candidates(:,4), ...
    LogL, AIC, BIC, ...
    'VariableNames', {'Model','p','q','P','Q','LogL','AIC','BIC'});
results = sortrows(results, 'AIC') %[output:676f4624]

%%
best = results.Model(1);
EstBest = models{best};
summarize(EstBest)   %[output:25004700]

cBest = candidates(best,:);
Xb = X;

e = infer(EstBest, y, 'X', Xb);           % innovations (white-noise part)
z = e ./ sqrt(EstBest.Variance);          % standardized residuals

figure; plot(timeTrain, z); title('Standardized residuals') %[output:255ca8bc]
figure; autocorr(z, NumLags=40); title('ACF of residuals - best model') %[output:5ee1a67b]
figure; parcorr(z, NumLags=40); title('PACF of residuals - best model') %[output:7e00a601]
figure; qqplot(z); title('QQ plot of residuals') %[output:8459a51d]

[hLB, pLB] = lbqtest(z, 'Lags', [10 14 21]) %[output:3128e249] %[output:50a7b2c5]
%%
%[text] ### Weekday Dummy model
%[text] 
%[text] 
%[text] 
%%
%[text] Functions
function [EstMdl, logL, numParams] = fitRegSARIMA(y, X, p, q, P, Q)
args = {};
if p > 0, args = [args {'ARLags',  1:p}];     end
if q > 0, args = [args {'MALags',  1:q}];     end
if P > 0, args = [args {'SARLags', 7*(1:P)}]; end
if Q > 0, args = [args {'SMALags', 7*(1:Q)}]; end

Mdl = regARIMA(args{:});              % intercept included by default (d = D = 0)
[EstMdl, ~, logL] = estimate(Mdl, y, 'X', X, 'Display', 'off');

% intercept + betas + AR + MA + SAR + SMA + innovation variance
numParams = 1 + size(X,2) + p + q + P + Q + 1;
end

